            let descriptor_start = usize::from(selector & !7);
            let expected_cs = [0xff, 0xff, 0, 0, 0, 0x9b, 0xaf, 0];
            let descriptor_matches = gdt_bytes.get(descriptor_start..descriptor_start + 8)
                == Some(expected_cs.as_slice());
