fn validate_cmpss_memory_rax_result(
    loaded: &LoadedFixture,
    result: &RunResult,
    snapshot: &Snapshot,
) -> Result<(), FormatError> {
    let fixture = &loaded.fixture;
    let controls = fixture
        .cmpss_memory_rax_controls
        .ok_or(FormatError::CaseMismatch("cmpss_memory_rax_controls"))?;
    let code = fixture
        .memory
        .iter()
        .find(|r| r.region_id == "code")
        .ok_or(FormatError::CaseMismatch("memory.code"))?;
    let bytes = decode_bytes(&code.initial_bytes_hex)?;
    if bytes.len() != 5 || bytes[..4] != [0xf3, 0x0f, 0xc2, 0x00] {
        return Err(FormatError::CaseMismatch("CMPSS m32 encoding"));
    }
    let predicate = bytes[4];
    let sse = fixture
        .initial_state
        .sse
        .as_ref()
        .ok_or(FormatError::CaseMismatch("state.sse"))?;
    let xmm0 = decode_bytes(&sse.xmm[0])?;
    let lhs = u32::from_le_bytes(
        xmm0[..4]
            .try_into()
            .map_err(|_| FormatError::CaseMismatch("xmm0"))?,
    );
    let data = fixture
        .memory
        .iter()
        .find(|r| r.region_id == "data")
        .ok_or(FormatError::CaseMismatch("memory.data"))?;
    let data_bytes = decode_bytes(&data.initial_bytes_hex)?;
    let rhs = u32::from_le_bytes(
        data_bytes[..4]
            .try_into()
            .map_err(|_| FormatError::CaseMismatch("memory.data"))?,
    );
    let classify = |bits: u32| {
        let exponent = (bits >> 23) & 0xff;
        let fraction = bits & 0x007f_ffff;
        if exponent == 0xff && fraction != 0 {
            if fraction & (1 << 22) != 0 { 2 } else { 3 }
        } else if exponent == 0 && fraction != 0 {
            1
        } else {
            0
        }
    };
    let left_class = classify(lhs);
    let right_class = classify(rhs);
    let unordered = matches!(left_class, 2 | 3) || matches!(right_class, 2 | 3);
    let signaling_predicate = matches!(predicate, 1 | 2 | 5 | 6);
    let raised_ie = left_class == 3
        || right_class == 3
        || (unordered && signaling_predicate && (left_class == 2 || right_class == 2));
    let raised_de = !unordered && (left_class == 1 || right_class == 1);
    let ordering = if lhs & 0x7fff_ffff == 0 && rhs & 0x7fff_ffff == 0 {
        core::cmp::Ordering::Equal
    } else {
        let sign_l = lhs >> 31 != 0;
        let sign_r = rhs >> 31 != 0;
        match (sign_l, sign_r) {
            (true, false) => core::cmp::Ordering::Less,
            (false, true) => core::cmp::Ordering::Greater,
            (false, false) => lhs.cmp(&rhs),
            (true, true) => rhs.cmp(&lhs),
        }
    };
    let greater = !unordered && ordering == core::cmp::Ordering::Greater;
    let less = !unordered && ordering == core::cmp::Ordering::Less;
    let equal = !unordered && ordering == core::cmp::Ordering::Equal;
    let truth = match predicate {
        0 => equal,
        1 => less,
        2 => less || equal,
        3 => unordered,
        4 => !equal,
        5 => greater || equal || unordered,
        6 => greater || unordered,
        7 => !unordered,
        _ => false,
    };
    let gate = if !controls.sse_available || controls.cr0_em || !controls.cr4_osfxsr {
        Some(6)
    } else if controls.cr0_ts {
        Some(7)
    } else {
        None
    };
    let predicate_refusal = predicate > 7;
    let local_ac = gate.is_none() && fixture.initial_state.rflags.get() & (1 << 18) != 0;
    let source = fixture.initial_state.gpr[0].get();
    let last = source.checked_add(3);
    let canonical = |a: u64| a >> 47 == 0 || a >> 47 == 0x1ffff;
    let span_fault = last.is_none_or(|end| !canonical(source) || !canonical(end));
    let fault = if predicate_refusal {
        None
    } else {
        gate.or_else(|| (!local_ac && span_fault).then_some(13))
    };
    let unsupported = predicate_refusal || (gate.is_none() && local_ac);
    if !matches!(
        (fault, unsupported, fixture.expected_exit),
        (Some(_), false, ExpectedExit::Exception)
            | (None, true, ExpectedExit::Unsupported)
            | (None, false, ExpectedExit::StopAddress)
    ) {
        return Err(FormatError::CaseMismatch("CMPSS m32 expected exit"));
    }
    let mut expected = fixture.initial_state.clone();
    if gate.is_none() && !unsupported && fault.is_none() {
        let state_sse = expected
            .sse
            .as_mut()
            .ok_or(FormatError::CaseMismatch("state.sse"))?;
        state_sse.mxcsr =
            HexU64(sse.mxcsr.get() | u64::from(raised_ie) | (u64::from(raised_de) << 1));
        let mut output_xmm = decode_bytes(&state_sse.xmm[0])?;
        output_xmm[..4].copy_from_slice(&(if truth { u32::MAX } else { 0 }).to_le_bytes());
        state_sse.xmm[0] = crate::memory::encode_bytes(&output_xmm);
        expected.rip = HexU64(
            fixture
                .initial_state
                .rip
                .get()
                .checked_add(5)
                .ok_or(FormatError::CaseMismatch("CMPSS m32 RIP overflow"))?,
        );
    }
    let memory = fixture
        .memory
        .iter()
        .map(|region| MemoryRegionSnapshot {
            region_id: region.region_id.clone(),
            guest_address: region.guest_address,
            bytes_hex: region.initial_bytes_hex.clone(),
        })
        .collect::<Vec<_>>();
    if snapshot.state != expected
        || snapshot.rflags_defined != HexU64(INTEGER_FLAGS)
        || snapshot.memory != memory
    {
        return Err(FormatError::CaseMismatch("CMPSS m32 output state"));
    }
    if result.instructions_executed
        != (Observation::Available {
            value: HexU64(u64::from(fault.is_none() && !unsupported)),
        })
    {
        return Err(FormatError::CaseMismatch("CMPSS m32 retirement"));
    }
    match (fault, unsupported, &result.outcome, &snapshot.exception) {
        (
            Some(vector),
            false,
            Outcome::Exception {},
            Observation::Available {
                value: Some(exception),
            },
        ) if exception.vector == vector
            && exception.error_code
                == if vector == 13 {
                    Observation::Available { value: HexU64(0) }
                } else {
                    Observation::Unavailable {
                        reason: "exception has no architectural error code".into(),
                    }
                }
            && exception.faulting_rip == fixture.initial_state.rip
            && matches!(exception.fault_address, Observation::Unavailable { .. }) => {}
        (None, true, Outcome::Unsupported { .. }, Observation::Available { value: None }) => {}
        (None, false, Outcome::StopAddress {}, Observation::Available { value: None }) => {}
        _ => return Err(FormatError::CaseMismatch("CMPSS m32 outcome/exception")),
    }
    Ok(())
}

