fn validate_comparison_memory_rax_result(
    loaded: &LoadedFixture,
    result: &RunResult,
    snapshot: &Snapshot,
    quiet_nan_raises_ie: bool,
    binary32: bool,
    invalid_only: bool,
) -> Result<(), FormatError> {
    let fixture = &loaded.fixture;
    let (sse_available, cr0_em, cr0_ts, cr4_osfxsr, cr4_osxmmexcpt) = if fixture.profile
        == Profile::LongUcomisdMemoryInvalidRaxV1
    {
        let c = fixture
            .ucomisd_memory_rax_invalid_controls
            .ok_or(FormatError::CaseMismatch(
                "ucomisd_memory_rax_invalid_controls",
            ))?;
        (
            c.sse2_available,
            c.cr0_em,
            c.cr0_ts,
            c.cr4_osfxsr,
            c.cr4_osxmmexcpt,
        )
    } else if fixture.profile == Profile::LongComisdMemoryInvalidRaxV1 {
        let c = fixture
            .comisd_memory_rax_invalid_controls
            .ok_or(FormatError::CaseMismatch(
                "comisd_memory_rax_invalid_controls",
            ))?;
        (
            c.sse2_available,
            c.cr0_em,
            c.cr0_ts,
            c.cr4_osfxsr,
            c.cr4_osxmmexcpt,
        )
    } else if fixture.profile == Profile::LongUcomissMemoryInvalidRaxV1 {
        let c = fixture
            .ucomiss_memory_invalid_rax_controls
            .ok_or(FormatError::CaseMismatch(
                "ucomiss_memory_invalid_rax_controls",
            ))?;
        (
            c.sse_available,
            c.cr0_em,
            c.cr0_ts,
            c.cr4_osfxsr,
            c.cr4_osxmmexcpt,
        )
    } else if invalid_only {
        let c = fixture
            .comiss_memory_invalid_rax_controls
            .ok_or(FormatError::CaseMismatch(
                "comiss_memory_invalid_rax_controls",
            ))?;
        (
            c.sse_available,
            c.cr0_em,
            c.cr0_ts,
            c.cr4_osfxsr,
            c.cr4_osxmmexcpt,
        )
    } else if binary32 && quiet_nan_raises_ie {
        fixture
            .comiss_memory_rax_controls
            .map(|controls| {
                (
                    controls.sse_available,
                    controls.cr0_em,
                    controls.cr0_ts,
                    controls.cr4_osfxsr,
                    false,
                )
            })
            .ok_or(FormatError::CaseMismatch("comiss_memory_rax_controls"))?
    } else if binary32 {
        fixture
            .ucomiss_memory_rax_controls
            .map(|controls| {
                (
                    controls.sse_available,
                    controls.cr0_em,
                    controls.cr0_ts,
                    controls.cr4_osfxsr,
                    false,
                )
            })
            .ok_or(FormatError::CaseMismatch("ucomiss_memory_rax_controls"))?
    } else if quiet_nan_raises_ie {
        fixture
            .comisd_memory_rax_controls
            .map(|controls| {
                (
                    controls.sse2_available,
                    controls.cr0_em,
                    controls.cr0_ts,
                    controls.cr4_osfxsr,
                    false,
                )
            })
            .ok_or(FormatError::CaseMismatch("comisd_memory_rax_controls"))?
    } else {
        fixture
            .ucomisd_memory_rax_controls
            .map(|controls| {
                (
                    controls.sse2_available,
                    controls.cr0_em,
                    controls.cr0_ts,
                    controls.cr4_osfxsr,
                    false,
                )
            })
            .ok_or(FormatError::CaseMismatch("ucomisd_memory_rax_controls"))?
    };
    if fixture
        .memory
        .iter()
        .find(|region| region.region_id == "code")
        .is_none_or(|code| {
            !code
                .initial_bytes_hex
                .eq_ignore_ascii_case(if binary32 && quiet_nan_raises_ie {
                    "0f2f00"
                } else if binary32 {
                    "0f2e00"
                } else if quiet_nan_raises_ie {
                    "660f2f00"
                } else {
                    "660f2e00"
                })
        })
    {
        return Err(FormatError::CaseMismatch(
            if binary32 && quiet_nan_raises_ie {
                "COMISS m32 encoding"
            } else if binary32 {
                "UCOMISS m32 encoding"
            } else {
                "comparison m64 encoding"
            },
        ));
    }
    let initial_sse = fixture
        .initial_state
        .sse
        .as_ref()
        .ok_or(FormatError::CaseMismatch("state.sse"))?;
    let operand_width = if binary32 { 4 } else { 8 };
    let instruction_length: u64 = if binary32 { 3 } else { 4 };
    let left = if binary32 {
        u64::from(u32::from_le_bytes(
            decode_bytes(&initial_sse.xmm[0])?[..4]
                .try_into()
                .map_err(|_| FormatError::CaseMismatch("xmm0"))?,
        ))
    } else {
        u64::from_le_bytes(
            decode_bytes(&initial_sse.xmm[0])?[..8]
                .try_into()
                .map_err(|_| FormatError::CaseMismatch("xmm0"))?,
        )
    };
    let data = fixture
        .memory
        .iter()
        .find(|region| region.region_id == "data")
        .ok_or(FormatError::CaseMismatch("memory.data"))?;
    let data_bytes = decode_bytes(&data.initial_bytes_hex)?;
    let right = if binary32 {
        u64::from(u32::from_le_bytes(
            data_bytes[..4]
                .try_into()
                .map_err(|_| FormatError::CaseMismatch("memory.data"))?,
        ))
    } else {
        u64::from_le_bytes(
            data_bytes[..8]
                .try_into()
                .map_err(|_| FormatError::CaseMismatch("memory.data"))?,
        )
    };
    let classify = |bits: u64| {
        if binary32 {
            let exponent = (bits >> 23) & 0xff;
            let fraction = bits & 0x007f_ffff;
            if exponent == 0xff && fraction != 0 {
                if fraction & (1 << 22) != 0 { 3 } else { 4 }
            } else if exponent == 0 && fraction != 0 {
                2
            } else {
                0
            }
        } else {
            let exponent = (bits >> 52) & 0x7ff;
            let fraction = bits & 0x000f_ffff_ffff_ffff;
            if exponent == 0x7ff && fraction != 0 {
                if fraction & (1 << 51) != 0 { 3 } else { 4 }
            } else if exponent == 0 && fraction != 0 {
                2
            } else {
                0
            }
        }
    };
    let left_class = classify(left);
    let right_class = classify(right);
    let unordered = matches!(left_class, 3 | 4) || matches!(right_class, 3 | 4);
    let raised_ie = unordered && (quiet_nan_raises_ie || left_class == 4 || right_class == 4);
    let subnormal = left_class == 2 || right_class == 2;
    let raised_de = !invalid_only && !unordered && subnormal;
    let old_mxcsr = initial_sse.mxcsr.get() as u32;
    let gate = if !sse_available || cr0_em || !cr4_osfxsr {
        Some(6)
    } else if cr0_ts {
        Some(7)
    } else {
        None
    };
    let local_ac_refusal = fixture.initial_state.rflags.get() & (1 << 18) != 0;
    let source = fixture.initial_state.gpr[0].get();
    let last = source.checked_add((operand_width - 1) as u64);
    let canonical48 = |address: u64| address >> 47 == 0 || address >> 47 == 0x1ffff;
    let span_fault = last.is_none_or(|end| !canonical48(source) || !canonical48(end));
    let pre_read_fault = gate.or_else(|| (!local_ac_refusal && span_fault).then_some(13));
    let post_read_refusal =
        invalid_only && gate.is_none() && !local_ac_refusal && !span_fault && subnormal;
    let ie_unmasked = invalid_only
        && raised_ie
        && old_mxcsr & (1 << 7) == 0
        && gate.is_none()
        && !local_ac_refusal
        && !span_fault;
    let fault = pre_read_fault.or_else(|| {
        (ie_unmasked && !post_read_refusal).then_some(if cr4_osxmmexcpt { 19 } else { 6 })
    });
    let unsupported = gate.is_none() && (local_ac_refusal || post_read_refusal);
    if !matches!(
        (fault, unsupported, fixture.expected_exit),
        (Some(_), false, ExpectedExit::Exception)
            | (None, true, ExpectedExit::Unsupported)
            | (None, false, ExpectedExit::StopAddress)
    ) {
        return Err(FormatError::CaseMismatch("comparison m64 expected exit"));
    }
    let mut expected = fixture.initial_state.clone();
    if invalid_only && fault.is_some() && pre_read_fault.is_none() && !unsupported && ie_unmasked {
        let sse = expected
            .sse
            .as_mut()
            .ok_or(FormatError::CaseMismatch("state.sse"))?;
        sse.mxcsr = HexU64(u64::from(old_mxcsr | 1));
    }
    if gate.is_none() && !unsupported && fault.is_none() {
        let sse = expected
            .sse
            .as_mut()
            .ok_or(FormatError::CaseMismatch("state.sse"))?;
        sse.mxcsr = HexU64(u64::from(
            old_mxcsr | u32::from(raised_ie) | (u32::from(raised_de) << 1),
        ));
        let arithmetic_flags = (1 << 0) | (1 << 2) | (1 << 4) | (1 << 6) | (1 << 7) | (1 << 11);
        let mut new_flags = fixture.initial_state.rflags.get() & !arithmetic_flags;
        if unordered {
            new_flags |= (1 << 0) | (1 << 2) | (1 << 6);
        } else {
            let magnitude_mask = if binary32 {
                0x7fff_ffff
            } else {
                0x7fff_ffff_ffff_ffff
            };
            let ordering = if left & magnitude_mask == 0 && right & magnitude_mask == 0 {
                core::cmp::Ordering::Equal
            } else {
                let sign_bit = if binary32 { 31 } else { 63 };
                match (
                    ((left >> sign_bit) & 1) != 0,
                    ((right >> sign_bit) & 1) != 0,
                ) {
                    (false, true) => core::cmp::Ordering::Greater,
                    (true, false) => core::cmp::Ordering::Less,
                    (false, false) => (left & magnitude_mask).cmp(&(right & magnitude_mask)),
                    (true, true) => (right & magnitude_mask).cmp(&(left & magnitude_mask)),
                }
            };
            match ordering {
                core::cmp::Ordering::Less => new_flags |= 1,
                core::cmp::Ordering::Equal => new_flags |= 1 << 6,
                core::cmp::Ordering::Greater => {}
            }
        }
        expected.rflags = HexU64(new_flags);
        expected.rip = HexU64(
            fixture
                .initial_state
                .rip
                .get()
                .checked_add(instruction_length)
                .ok_or(FormatError::CaseMismatch("comparison m64 RIP overflow"))?,
        );
    }
    let memory = fixture
        .memory
        .iter()
        .map(|region| MemoryRegionSnapshot {
            region_id: region.region_id.clone(),
            guest_address: region.guest_address,
            bytes_hex: region.initial_bytes_hex.clone(),
        })
        .collect::<Vec<_>>();
    if snapshot.state != expected
        || snapshot.rflags_defined != HexU64(INTEGER_FLAGS)
        || snapshot.memory != memory
    {
        return Err(FormatError::CaseMismatch(if binary32 {
            "COMISS m32 output state"
        } else {
            "comparison m64 output state"
        }));
    }
    if result.instructions_executed
        != (Observation::Available {
            value: HexU64(u64::from(fault.is_none() && !unsupported)),
        })
    {
        return Err(FormatError::CaseMismatch("comparison m64 retirement"));
    }
    match (fault, unsupported, &result.outcome, &snapshot.exception) {
        (
            Some(vector),
            false,
            Outcome::Exception {},
            Observation::Available {
                value: Some(exception),
            },
        ) if exception.vector == vector
            && exception.error_code
                == if vector == 13 {
                    Observation::Available { value: HexU64(0) }
                } else {
                    Observation::Unavailable {
                        reason: "exception has no architectural error code".into(),
                    }
                }
            && exception.faulting_rip == fixture.initial_state.rip
            && matches!(exception.fault_address, Observation::Unavailable { .. }) => {}
        (None, true, Outcome::Unsupported { .. }, Observation::Available { value: None }) => {}
        (None, false, Outcome::StopAddress {}, Observation::Available { value: None }) => {}
        _ => {
            return Err(FormatError::CaseMismatch(
                "comparison m64 outcome/exception",
            ));
        }
    }
    Ok(())
}

fn comisd_ucomisd_register_encoding(code_bytes: &str) -> Option<(bool, u8, u8, u32)> {
    if code_bytes.len() % 2 != 0 {
        return None;
    }
    let bytes = (0..code_bytes.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&code_bytes[i..i + 2], 16).ok())
        .collect::<Option<Vec<_>>>()?;
    let (rex, op, modrm) = match bytes.as_slice() {
        [0x66, 0x0f, op @ (0x2e | 0x2f), m] => (0u8, *op, *m),
        [0x66, rex, 0x0f, op @ (0x2e | 0x2f), m] if matches!(*rex, 0x41 | 0x44 | 0x45) => {
            (*rex, *op, *m)
        }
        _ => return None,
    };
    if modrm >> 6 != 3 {
        return None;
    }
    let d = ((modrm >> 3) & 7) | (((rex >> 2) & 1) << 3);
    let r = (modrm & 7) | ((rex & 1) << 3);
    if (d >= 8 || r >= 8) != (bytes.len() == 5)
        || (rex & 4 != 0) != (d >= 8)
        || (rex & 1 != 0) != (r >= 8)
        || rex & 0x0a != 0
    {
        return None;
    }
    Some((op == 0x2e, d, r, bytes.len() as u32))
}

fn cvtsi2sd_r32_register_length(code_bytes: &str) -> Option<u32> {
    code_bytes.eq_ignore_ascii_case("f20f2ac0").then_some(4)
}

fn cvtsi2sd_r64_register_length(code_bytes: &str) -> Option<u32> {
    code_bytes.eq_ignore_ascii_case("f2480f2ac0").then_some(5)
}

/// Independently parse the complete canonical Long64 CVTSI2SD register encoding.
fn cvtsi2sd_register_encoding(code_bytes: &str) -> Option<(bool, u8, u8, u32)> {
    if code_bytes.len() % 2 != 0 {
        return None;
    }
    let bytes = (0..code_bytes.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&code_bytes[index..index + 2], 16).ok())
        .collect::<Option<Vec<_>>>()?;
    let (rex, modrm) = match bytes.as_slice() {
        [0xf2, 0x0f, 0x2a, modrm] => (0u8, *modrm),
        [0xf2, rex, 0x0f, 0x2a, modrm] => (*rex, *modrm),
        _ => return None,
    };
    if modrm >> 6 != 3 {
        return None;
    }
    let wide = rex & 8 != 0;
    let destination = ((modrm >> 3) & 7) | (((rex >> 2) & 1) << 3);
    let source = (modrm & 7) | ((rex & 1) << 3);
    let expected_rex = match (wide, destination >= 8, source >= 8) {
        (false, false, false) => None,
        (false, true, false) => Some(0x44),
        (false, false, true) => Some(0x41),
        (false, true, true) => Some(0x45),
        (true, false, false) => Some(0x48),
        (true, true, false) => Some(0x4c),
        (true, false, true) => Some(0x49),
        (true, true, true) => Some(0x4d),
    };
    if (bytes.len() == 4 && expected_rex.is_none())
        || (bytes.len() == 5 && expected_rex == Some(rex))
    {
        Some((wide, destination, source, bytes.len() as u32))
    } else {
        None
    }
}

/// Independently parse the complete canonical Long64 CVTSI2SS register encoding.
fn cvtsi2ss_register_encoding(code_bytes: &str) -> Option<(bool, u8, u8, u32)> {
    if code_bytes.len() % 2 != 0 {
        return None;
    }
    let bytes = (0..code_bytes.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&code_bytes[index..index + 2], 16).ok())
        .collect::<Option<Vec<_>>>()?;
    let (rex, modrm) = match bytes.as_slice() {
        [0xf3, 0x0f, 0x2a, modrm] => (0u8, *modrm),
        [0xf3, rex, 0x0f, 0x2a, modrm] => (*rex, *modrm),
        _ => return None,
    };
    if modrm >> 6 != 3 {
        return None;
    }
    let wide = rex & 8 != 0;
    let destination = ((modrm >> 3) & 7) | (((rex >> 2) & 1) << 3);
    let source = (modrm & 7) | ((rex & 1) << 3);
    let expected_rex = match (wide, destination >= 8, source >= 8) {
        (false, false, false) => None,
        (false, true, false) => Some(0x44),
        (false, false, true) => Some(0x41),
        (false, true, true) => Some(0x45),
        (true, false, false) => Some(0x48),
        (true, false, true) => Some(0x49),
        (true, true, false) => Some(0x4c),
        (true, true, true) => Some(0x4d),
    };
    let actual_rex = if bytes.len() == 5 {
        Some(bytes[1])
    } else {
        None
    };
    if actual_rex != expected_rex {
        return None;
    }
    Some((wide, destination, source, bytes.len() as u32))
}

